// REQ-SEL6 · Ver el pivote de la selección en reposo (con corchetes/brackets completos)
// Intercepta mcDrawOverlays para que, al tener una selección activa en reposo (sin Ctrl pulsado),
// dibuje la celda pivote con sus aristas y brackets (líneas o vóxeles 3D según game.selVoxeles).
//
// API:
//   game.selPivoteVisible.on()
//   game.selPivoteVisible.off()
//   game.selPivoteVisible.estado()

(() => {
'use strict';

let activo = false;
let origMcDrawOverlays = null;

function patchedDrawOverlays(pj, view){
  if (origMcDrawOverlays) origMcDrawOverlays(pj, view);

  if (!mc.active || !mc.gl || !mc.structLoc || !mc.structProg) return;
  if (mc.tool !== 'select' || mc.escaparate || mc.pasteActive || mc._guardada) return;
  if (!mc.selCajas || !mc.selCajas.length) return;

  // Si Ctrl está pulsado, el motor ya muestra el hover
  if (mc.selCtrlHeld) return;

  // Si hay pivote fijado, el motor original ya lo pinta
  const tieneFijado = (typeof mcSelCajaDe === 'function' && mcSelCajaDe(mc.selPivote) >= 0);
  if (tieneFijado) return;

  // Pivote por defecto (esquina mínima [x0, y0, z0] de la caja activa)
  const s = mc.selCajas[0];
  if (!s) return;
  const x0 = Math.min(s.a[0], s.b[0]);
  const y0 = Math.min(s.a[1], s.b[1]);
  const z0 = Math.min(s.a[2], s.b[2]);

  const gl = mc.gl;
  const SL = mc.structLoc;
  const selLines = [];
  const selVox = [];
  const mag = [1.0, 0.25, 0.85]; // Magenta

  const vox = !!(mc.selVoxeles && mc.selVoxeles.activo);

  if (typeof mcPushBoxEdges === 'function') {
    mcPushBoxEdges(selLines, x0, y0, z0, x0 + 1, y0 + 1, z0 + 1, mag[0], mag[1], mag[2]);
  }

  if (vox && typeof mcPushVoxCorchetes === 'function') {
    mcPushVoxCorchetes(selVox, x0, y0, z0, x0 + 1, y0 + 1, z0 + 1, mc.selVoxeles, mag[0], mag[1], mag[2], null);
  } else if (typeof mcPushCornerBrackets === 'function') {
    mcPushCornerBrackets(selLines, x0, y0, z0, x0 + 1, y0 + 1, z0 + 1, 0.45, mag[0], mag[1], mag[2]);
  }

  gl.useProgram(mc.structProg);
  gl.uniformMatrix4fv(SL.uProj, false, pj.m);
  gl.uniformMatrix4fv(SL.uView, false, view);
  if (typeof MC_IDENT !== 'undefined') gl.uniformMatrix4fv(SL.uModel, false, MC_IDENT);

  // Dibujar líneas de aristas (y corchetes si no es modo vox)
  if (selLines.length) {
    gl.enable(gl.DEPTH_TEST);
    gl.depthMask(false);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.CONSTANT_ALPHA, gl.ONE_MINUS_CONSTANT_ALPHA);
    gl.blendColor(0, 0, 0, 0.98);
    if (typeof mcDrawArr === 'function') mcDrawArr(SL, selLines, gl.LINES);
    gl.disable(gl.BLEND);
    gl.depthMask(true);
  }

  // Dibujar corchetes de vóxeles 3D (cuando game.selVoxeles está activo)
  if (selVox.length) {
    gl.frontFace(gl.CW);
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);
    gl.depthMask(true);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.CONSTANT_ALPHA, gl.ONE_MINUS_CONSTANT_ALPHA);
    gl.blendColor(0, 0, 0, 0.98);
    if (typeof mcDrawArr === 'function') mcDrawArr(SL, selVox, gl.TRIANGLES);
    gl.depthMask(false);
    gl.disable(gl.CULL_FACE);
    gl.frontFace(gl.CCW);
    gl.disable(gl.BLEND);
    gl.depthMask(true);
  }
}

function instalar(){
  if (typeof window.mcDrawOverlays === 'function' && !origMcDrawOverlays) {
    origMcDrawOverlays = window.mcDrawOverlays;
    window.mcDrawOverlays = patchedDrawOverlays;
    activo = true;
    console.log('✅ REQ-SEL6: interceptor mcDrawOverlays con brackets 3D instalado');
  }
}

function desinstalar(){
  if (origMcDrawOverlays) {
    window.mcDrawOverlays = origMcDrawOverlays;
    origMcDrawOverlays = null;
    activo = false;
    console.log('❌ REQ-SEL6: interceptor mcDrawOverlays desinstalado');
  }
}

const API = {
  on(){ if(!activo) instalar(); return 'REQ-SEL6 activado'; },
  off(){ if(activo) desinstalar(); return 'REQ-SEL6 desactivado'; },
  estado(){ return 'REQ-SEL6: ' + (activo ? 'ACTIVO' : 'inactivo'); }
};

game.selPivoteVisible = API;
API.on();
})();
